"use client"

import { motion, useScroll, useSpring } from "motion/react"

export function ScrollProgressBar() {
  const { scrollYProgress } = useScroll()
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 200,
    damping: 30,
    restDelta: 0.001,
  })

  return (
    <motion.div
      aria-hidden
      className="fixed left-0 top-0 z-100 h-[2px] w-full origin-left bg-primary"
      style={{ scaleX }}
    />
  )
}
